"""从保存的官方 MaGRoad model.py 机械提取推理路径，不改网络层和 forward 计算。

去除 pytorch_lightning/torchmetrics/fvcore/detectron2 依赖、训练损失和 SAM 初始权重读取；
完整 MaGRoad checkpoint 随后以 strict=True 加载全部参数。
"""
from __future__ import annotations

import ast
from pathlib import Path

KEEP_FUNCTIONS = {'fourier_encode_angle', 'softmin', 'normalize_grid', 'sample_line_points', 'build_edge_bias'}
KEEP_CLASSES = {'BilinearSampler', 'TopoNet', 'GeodesicPathExtractor', 'BiasedSelfAttentionLayer',
                'MaGTopoNet', '_LoRA_qkv', 'MaGRoad'}
KEEP_METHODS = {'__init__', 'forward', 'infer_masks_and_img_features', 'infer_toponet'}


def generate() -> str:
    root = Path(__file__).resolve().parent
    module = ast.parse((root/'upstream_model.py.txt').read_text(encoding='utf-8'))
    items = []
    for item in module.body:
        if isinstance(item, ast.FunctionDef) and item.name in KEEP_FUNCTIONS:
            items.append(item)
        elif isinstance(item, ast.ClassDef) and item.name in KEEP_CLASSES:
            if item.name == 'MaGRoad':
                item.bases = [ast.parse('nn.Module', mode='eval').body]
                methods = []
                for method in item.body:
                    if not isinstance(method, ast.FunctionDef) or method.name not in KEEP_METHODS:
                        continue
                    if method.name == '__init__':
                        cutoff = next(i for i, statement in enumerate(method.body)
                                      if isinstance(statement, ast.If) and ast.unparse(statement.test) == 'self.config.FOCAL_LOSS')
                        # Losses/metrics/SAM 初始权重读取均在 FOCAL_LOSS 分支之后，推理不需要。
                        method.body = method.body[:cutoff]
                    methods.append(method)
                item.body = methods
            items.append(item)
    missing = (KEEP_FUNCTIONS | KEEP_CLASSES) - {item.name for item in items}
    if missing:
        raise RuntimeError(f'上游源码缺少 {sorted(missing)}')
    imports = '''# Generated by build_inference_model.py from upstream_model.py.txt.
# Architecture and inference methods are preserved; see SOURCE.json and LICENSE.magroad.
import math
from functools import partial
from typing import List, Optional

import torch
import torch.nn.functional as F
from torch import nn

from .sam_modeling.common import LayerNorm2d
from .sam_modeling.image_encoder import ImageEncoderViT

'''
    return imports + '\n\n'.join(ast.unparse(item) for item in items) + '\n'


if __name__ == '__main__':
    (Path(__file__).parent/'model.py').write_text(generate(), encoding='utf-8')
